func memberCallName(receiverName, receiverType, method string) string {
	if receiverName != "" {
		return receiverName + "." + method
	}
	if receiverType != "" {
		return receiverType + "." + method
	}
	return "." + method
}

func runtimeObjectType(value Value) string {
	if value.Runtime != "" {
		return value.Runtime
	}
	return value.Type
}

