func compareVersionValues(left, right Value) int {
	for _, field := range []string{"major", "minor", "patch"} {
		lv := versionComponent(left, field)
		rv := versionComponent(right, field)
		if lv < rv {
			return -1
		}
		if lv > rv {
			return 1
		}
	}
	return 0
}

